from __future__ import annotations

import os
import re

import numpy as np

from dpdata.utils import open_file

from .scf import (
    bohr2ang,
    collect_force,
    collect_stress,
    get_geometry_in,
    get_mag_force,
    kbar2evperang3,
)
from .stru import get_frame_from_stru


def get_log_file(fname, inlines):
    suffix = "ABACUS"
    calculation = "scf"
    for line in inlines:
        if "suffix" in line and "suffix" == line.split()[0]:
            suffix = line.split()[1]
        elif "calculation" in line and "calculation" == line.split()[0]:
            calculation = line.split()[1]
    logf = os.path.join(fname, f"OUT.{suffix}/running_{calculation}.log")
    return logf


def _is_energy(line):
    return line.lstrip().startswith("final etot is") or "#TOTAL ENERGY#" in line


def _is_scf_end(line):
    return _is_energy(line) or "convergence has not been achieved" in line.lower()


def _step_blocks(loglines):
    """Locate ionic attempts, including attempts without a converged energy."""
    starts = []
    for i, line in enumerate(loglines):
        match = re.match(r"\s*RELAX IONS\s*:\s*\d+.*in total:\s*(\d+)", line)
        if match is None:
            match = re.match(r"\s*STEP OF RELAXATION\s*:\s*(\d+)", line)
        if match is not None:
            starts.append((i, int(match[1])))

    # Older/minimal logs have no ionic-step headings. Electronic convergence
    # markers still delimit the evaluated structures and their following labels.
    if not starts:
        starts = [
            (i, step)
            for step, i in enumerate(
                (i for i, line in enumerate(loglines) if _is_scf_end(line)), 1
            )
        ]

    for index, (start, step) in enumerate(starts):
        end = starts[index + 1][0] if index + 1 < len(starts) else len(loglines)
        # Geometry printed after the labels is the input to the *next* attempt.
        geometry_end = next(
            (
                i
                for i in range(start, end)
                if _is_scf_end(loglines[i])
                or "TOTAL-FORCE" in loglines[i]
                or "TOTAL-STRESS" in loglines[i]
            ),
            end - 1,
        )
        yield step, geometry_end, loglines[start:end]


def _geometry_events(loglines, natoms):
    """Read geometry updates, keeping fractional coordinates until the cell is known."""
    a0 = None
    for i, line in enumerate(loglines):
        if "lattice constant (Bohr)" in line:
            a0 = float(line.split()[-1])
        elif "Lattice vectors: (Cartesian coordinate: in unit of a_0)" in line:
            if a0 is None:
                raise ValueError("Missing lattice constant in ABACUS relaxation log")
            cell = np.array(
                [[float(x) for x in row.split()[:3]] for row in loglines[i + 1 : i + 4]]
            )
            if cell.shape != (3, 3):
                raise ValueError("Incomplete lattice vectors in ABACUS relaxation log")
            yield i, "cell", cell * a0 * bohr2ang
        else:
            match = re.match(r"\s*(DIRECT|CARTESIAN)\s+COORDINATES\b", line)
            if match is None:
                continue
            coords = np.array(
                [
                    [float(x) for x in row.split()[1:4]]
                    for row in loglines[i + 2 : i + 2 + natoms]
                ]
            )
            if coords.shape != (natoms, 3):
                raise ValueError("Incomplete coordinates in ABACUS relaxation log")
            direct = match[1] == "DIRECT"
            if not direct:
                unit = re.search(
                    r"UNIT\s*=\s*([+\-\d.eE]+)\s*(Bohr|Angstrom)", line, re.I
                )
                scale = a0
                if unit is not None:
                    scale = float(unit[1])
                    if unit[2].lower() == "angstrom":
                        scale /= bohr2ang
                if scale is None:
                    raise ValueError("Missing Cartesian coordinate unit in ABACUS log")
                coords *= scale * bohr2ang
            yield i, "coords", (coords, direct)


def _last_label(values, shape):
    if len(values):
        value = np.asarray(values[-1])
        if value.shape == shape:
            return value
    return None


def _get_relaxation_data(loglines, natoms, initial=None, output_dir=None):
    """Assemble complete labelled frames by ionic attempt, never by list length.

    ABACUS writes STRU_ION<n>_D after updating the geometry at attempt n.
    Thus it supplies the geometry for attempt n+1. The unnumbered STRU_ION_D
    is a final/restart structure and cannot supply intermediate frames.
    Log coordinates take precedence; snapshots recover missing coordinates.
    Cells may persist between attempts, but missing atomic positions must not
    be silently replaced by those of an earlier attempt.
    """
    natoms_log = sum(
        int(line.split()[-1])
        for line in loglines
        if "number of atom for this type" in line
    )
    assert natoms_log > 0 and natoms_log == natoms, (
        f"ERROR: detected atom number in log file is {natoms_log}, while the atom number in STRU file is {natoms}"
    )

    # A run can stop while printing the next trial structure. It cannot affect
    # any labelled frame, so do not parse geometry beyond the last energy.
    last_energy = max(
        (i for i, line in enumerate(loglines) if _is_energy(line)), default=-1
    )
    events = iter(_geometry_events(loglines[: last_energy + 1], natoms))
    event = next(events, None)
    records = []
    label_shapes = {
        "forces": (natoms, 3),
        "stress": (3, 3),
        "spins": (natoms, 3),
        "force_mags": (natoms, 3),
    }
    for step, geometry_end, block in _step_blocks(loglines):
        cell = coord = None
        while event is not None and event[0] <= geometry_end:
            if event[1] == "cell":
                cell = event[2]
            else:
                coord = event[2]
            event = next(events, None)

        energies = [float(line.split()[-2]) for line in block if _is_energy(line)]
        magmom, magforce = get_mag_force(block)
        record = {
            "step": step,
            "energy": energies[-1] if energies else None,
            "cell": cell,
            "coord": coord,
            "forces": _last_label(collect_force(block), label_shapes["forces"]),
            "stress": _last_label(collect_stress(block), label_shapes["stress"]),
            "spins": _last_label(magmom, label_shapes["spins"]),
            "force_mags": _last_label(magforce, label_shapes["force_mags"]),
        }
        records.append(record)

    # An entirely absent optional label remains absent. When it is printed,
    # exclude incomplete attempts using the same selection for every property.
    labels = [key for key in label_shapes if any(r[key] is not None for r in records)]
    frames = []
    cell = initial["cells"][0] if initial is not None else None
    for index, record in enumerate(records):
        if record["cell"] is not None:
            cell = record["cell"]
        if record["energy"] is None or any(record[key] is None for key in labels):
            continue
        coord = record["coord"]
        if coord is None:
            geometry = None
            if index == 0 and initial is not None:
                geometry = initial
            elif output_dir is not None:
                path = os.path.join(output_dir, f"STRU_ION{record['step'] - 1}_D")
                if os.path.isfile(path):
                    geometry = get_frame_from_stru(path)
                    if initial is not None and (
                        geometry["atom_names"] != initial["atom_names"]
                        or geometry["atom_numbs"] != initial["atom_numbs"]
                        or not np.array_equal(geometry["atom_types"], initial["atom_types"])
                    ):
                        raise ValueError(f"Atom identity/order in {path} differs from STRU")
            if geometry is None:
                raise ValueError(
                    f"Cannot recover geometry for ABACUS relaxation step {record['step']}: "
                    "no log coordinates or matching preceding STRU_ION snapshot"
                )
            cell = geometry["cells"][0]
            coord = geometry["coords"][0], False
        if cell is None:
            raise ValueError(f"Missing cell for ABACUS relaxation step {record['step']}")
        coords, direct = coord
        record["cells"] = cell
        record["coords"] = coords @ cell if direct else coords
        frames.append(record)

    data = {
        "energies": np.array([r["energy"] for r in frames]),
        "cells": np.array([r["cells"] for r in frames]).reshape(-1, 3, 3),
        "coords": np.array([r["coords"] for r in frames]).reshape(-1, natoms, 3),
    }
    for key in labels:
        data[key] = np.array([r[key] for r in frames]).reshape(-1, *label_shapes[key])
    if "stress" in data:
        # ABACUS stress is in kbar, and dpdata virials are in eV.
        volume = np.abs(np.linalg.det(data["cells"]))
        data["virials"] = data["stress"] * kbar2evperang3 * volume[:, None, None]
    if initial is not None and "move" in initial:
        data["move"] = np.repeat(initial["move"], len(frames), axis=0)
    return data


def get_coords_from_log(loglines, natoms):
    """Read complete relaxation frames from a log with coordinates (in Angstrom)."""
    data = _get_relaxation_data(loglines, natoms)
    return (
        data["energies"],
        data["cells"],
        data["coords"],
        data.get("forces", np.empty((0, natoms, 3))),
        data.get("stress", np.empty((0, 3, 3))),
        data.get("virials"),
    )


def get_frame(fname):
    if not isinstance(fname, str):
        raise RuntimeError("invalid input")
    with open_file(os.path.join(fname, "INPUT")) as fp:
        inlines = fp.read().split("\n")
    geometry_path_in = get_geometry_in(fname, inlines)
    data = get_frame_from_stru(geometry_path_in)
    natoms = sum(data["atom_numbs"])
    # Initial magnetic moments are inputs, not converged magnetic labels.
    data.pop("spins", None)

    logf = get_log_file(fname, inlines)
    assert os.path.isfile(logf), f"Error: can not find {logf}"
    with open_file(logf) as fp:
        lines = fp.readlines()
    data.update(_get_relaxation_data(lines, natoms, data, os.path.dirname(logf)))
    data["orig"] = np.zeros(3)
    return data
